export const reportsRelaysResponsePairsItemTlsFailedDefault = 0;

export const ReportsRelaysResponse = zod.object({
	note: zod.string(),
	pairs: zod.array(
		zod.object({
			exit: zod.string(),
			exit_id: zod.int(),
			in_bytes: zod.union([zod.int(), zod.null()]),
			loss_pct: zod.union([zod.number(), zod.null()]),
			out_bytes: zod.union([zod.int(), zod.null()]),
			relay: zod.string(),
			relay_id: zod.int(),
			rtt_ms: zod.union([zod.number(), zod.null()]),
			samples: zod.int(),
			tcp_fail_pct: zod.union([zod.number(), zod.null()]).optional(),
			tcp_rtt_ms: zod.union([zod.number(), zod.null()]).optional(),
			tcp_samples: zod.int().default(reportsRelaysResponsePairsItemTcpSamplesDefault),
			tls_failed: zod.int().default(reportsRelaysResponsePairsItemTlsFailedDefault),
			verdict: zod.string(),
		}),
	),
	ping_window_s: zod.int(),
	problems: zod.int(),
	since: zod.int(),
	truncated: zod.boolean(),
	until: zod.int(),
});

/**
 * Fleet and per-server bytes, peak day and hour, relay-exit pair bytes (default 7 days).
 * @summary Traffic
 */
export const reportsTrafficQueryFormatDefault = `json`;

export const ReportsTrafficQueryParams = zod.object({
	since: zod.union([zod.int(), zod.null()]).optional(),
	until: zod.union([zod.int(), zod.null()]).optional(),
	format: zod.string().default(reportsTrafficQueryFormatDefault),
});

export const ReportsTrafficHeader = zod.object({
	authorization: zod.union([zod.string(), zod.null()]).optional(),
});

export const ReportsTrafficResponse = zod.object({
	daily: zod.array(
		zod.object({
			day_start: zod.int(),
			rx: zod.int(),
			total: zod.int(),
			tx: zod.int(),
		}),
	),
	fleet: zod.object({
		exit: zod.int(),
		other: zod.int(),
		relay: zod.int(),
		rx: zod.int(),
		total: zod.int(),
		tx: zod.int(),
	}),
	link_pairs: zod.array(
		zod.object({
			in_bytes: zod.int(),
			out_bytes: zod.int(),
			peer: zod.string(),
			server: zod.string(),
			server_role: zod.string(),
		}),
	),
	note: zod.string(),
	peak_day: zod.union([
		zod.object({
			bytes: zod.int(),
			day_start: zod.int(),
		}),
		zod.null(),
	]),
	peak_hour: zod.union([
		zod.object({
			bytes: zod.int(),
			hour_start: zod.int(),
		}),
		zod.null(),
	]),
	servers: zod.array(
		zod.object({
			role: zod.string(),
			rx: zod.int(),
			server: zod.string(),
			server_id: zod.int(),
			total: zod.int(),
			tx: zod.int(),
		}),
	),
	since: zod.int(),
	truncated: zod.boolean(),
	until: zod.int(),
});
